function reviews(){const d=data;$('#attendance-view').innerHTML=`<section class="panel"><h2>Attendance corrections</h2>${table(['Employee','Date','Reason / proposed times','Status','Review'],d.pending.map(c=>{const p=JSON.parse(c.proposal_json);return [`${esc(c.employee_name)}<br><span class="subtle">${esc(c.employee_id)}</span>`,esc(c.business_date),`${esc(c.reason)}<br><span class="subtle">${p.explanationOnly?'Explanation only':time(p.clockIn)+' – '+time(p.clockOut)}</span>`,pill(c.status),`<button class="secondary" data-decision="${c.id}" data-kind="correction">Review</button>`]}))}</section><section class="panel"><h2>Work arrangements</h2>${table(['Employee','Context / period','Reason','Status','Review'],d.arrangements.map(a=>[`${esc(a.employee_name)}<br><span class="subtle">${esc(a.employee_id)}</span>`,`${esc(a.context)}<br><span class="subtle">${time(a.starts_at)} – ${time(a.ends_at)}</span>`,esc(a.reason),pill(a.status),`<button class="secondary" data-decision="${a.id}" data-kind="arrangement">Review</button>`]))}</section>`;if(isAdmin&&d.devices?.length){$('#attendance-view').insertAdjacentHTML('beforeend','<section class="panel"><h2>Device registration review</h2>'+table(['Employee','Device','Status','Review'],d.devices.map(x=>[esc(x.employeeName),esc(x.name),pill(x.status),'<button class="secondary" data-device="'+esc(x.id)+'">Review device</button>']))+'</section>');document.querySelectorAll('[data-device]').forEach(btn=>btn.onclick=()=>{const item=d.devices.find(x=>x.id===btn.dataset.device);dialog('Review attendance device',select('status','Device status',['Trusted','Revoked'],'Trusted')+'<label>Review note<textarea name="note" required></textarea></label>',f=>mutate('/device-decision',{id:item.id,version:item.version,status:f.get('status'),note:f.get('note')}))})}document.querySelectorAll('[data-decision]').forEach(btn=>btn.onclick=()=>{const kind=btn.dataset.kind,r=(kind==='correction'?d.pending:d.arrangements).find(x=>x.id===btn.dataset.decision);dialog('Review '+(kind==='correction'?'attendance correction':'work arrangement'),`<p>${esc(r.employee_name)} · ${esc(r.reason)}</p>${select('decision','Decision',['Approve','Reject'],'Approve')}<label>Review note<textarea name="note" required></textarea></label><p class="subtle">${isManager&&kind==='correction'?'Approval sends this correction to P&C for final review.':'Original records remain in the audit trail.'}</p>`,f=>mutate('/decision',{kind,id:r.id,version:r.version,decision:f.get('decision').toLowerCase(),note:f.get('note')}),'Save decision')})}
function analytics(){const d=data;$('#attendance-view').innerHTML=`<section class="panel"><div class="section-tools"><h2>Attendance reports & payroll review</h2><div class="inline-tools">${!isLeader?'<button class="secondary" id="csv-export">Download CSV / Excel</button>':''}<button class="secondary" id="print-report">Print / save PDF</button></div></div>${dateFilters()}<p class="subtle">Attendance metrics require P&C approval before sharing with MPC. No score change or payroll deduction is applied.</p>${table(isLeader?['Department','Recorded days','Working hours']:['Employee','Recorded / expected days','Attendance / punctuality','Work / break hours','Late / exceptions','WFH / overtime',''],isLeader?d.departments.map(e=>[esc(e.department),e.recordedDays,e.workHours]):d.employees.map(e=>[`${esc(e.employee_name)}<br><span class="subtle">${esc(e.employee_id)} · ${esc(e.department)}</span>`,e.recordedDays+' / '+(e.expectedDays||'Unconfigured'),(e.attendanceRate??'—')+(e.attendanceRate==null?'':'%')+' / '+(e.punctualityRate??'—')+(e.punctualityRate==null?'':'%'),e.workHours+' / '+e.breakHours,e.lateOccurrences+' / '+e.exceptionSessions,e.wfhDays+' days / '+e.unapprovedOvertimeHours+'h',isAdmin?`<button class="plain" data-metrics="${esc(e.employee_id)}">Approve month for MPC</button>`:'']))}</section>`;$('#range-filter').onsubmit=e=>{e.preventDefault();load(true,'?'+new URLSearchParams(new FormData(e.target)))};$('#print-report').onclick=()=>window.print();if($('#csv-export'))$('#csv-export').onclick=()=>{location.href='/api/attendance/export?'+new URLSearchParams({from:d.from,to:d.to})};document.querySelectorAll('[data-metrics]').forEach(btn=>btn.onclick=()=>dialog('Approve attendance metrics for MPC',field('period','Reporting month','month',d.from.slice(0,7),'required')+'<p>Metrics will be available alongside MPC as supporting evidence. Existing MPC scores are preserved.</p>',f=>mutate('/approve-metrics',{employeeId:btn.dataset.metrics,period:f.get('period')}),'Approve metrics'))}
const settingFields=[['scheduleEnabled','Working-hour alerts','bool'],['effectiveFrom','Rules apply from','date'],['start','Normal start time','time'],['end','Normal end time','time'],['flexibleHours','Flexible schedule','bool'],['graceMinutes','Clock-in grace (minutes)','number'],['expectedMinutes','Expected net work (minutes)','number'],['maxBreakMinutes','Break review threshold (minutes)','number'],['overtimeEnabled','Calculate overtime for review','bool'],['minOvertimeMinutes','Minimum overtime (minutes)','number'],['managerApproval','Manager reviews corrections first','bool'],['locationMode','Location rule','location'],['accuracyMetres','Maximum location uncertainty (metres)','number'],['traceLevel','Work trace level','trace'],['requiredPresence','Require open Nadi page for Available / Focused Work','bool'],['focusedCameraRequired','Require webcam during Focused Work','bool'],['heartbeatGraceMinutes','Page check-in grace (minutes)','number'],['presenceMinutes','Presence request interval (minutes)','number'],['presenceExpiryMinutes','Presence response window (minutes)','number'],['cameraEnabled','Offer optional selfie after acknowledgement','bool'],['reminders','In-app reminders','bool'],['locationRetentionDays','Location / device retention (days)','number'],['traceRetentionDays','Activity / work update retention (days)','number'],['photoRetentionDays','Optional photo retention (days)','number']];
function settingForm(k,label,type,value){return type==='bool'?select(k,label,['No','Yes'],value?'Yes':'No'):type==='location'?'<label>'+esc(label)+'<select name="'+k+'">'+[['flag','Record and flag for review'],['explanation','Require an explanation'],['reject','Reject clock-in; allow exception request']].map(([v,l])=>'<option value="'+v+'" '+(v===value?'selected':'')+'>'+l+'</option>').join('')+'</select></label>':type==='trace'?select(k,label,['1 · Clock & self updates','2 · Aggregated activity','3 · Activity & presence requests'],value+' · '+({1:'Clock & self updates',2:'Aggregated activity',3:'Activity & presence requests'}[value])):field(k,label,type,value,type==='number'?'min="0" max="10000"':'')}
function settingsView(){const c=settings.data;$('#attendance-view').innerHTML=`<form id="settings-form"><section class="panel"><div class="section-tools"><h2>Attendance rules</h2><button type="submit">Save rules</button></div><p class="subtle">Required page checks apply to Available and Focused Work. Focused Work can also require a webcam. The page may stay open in the background while staff use other apps. Mouse-only totals report about every three minutes; outside-page time is not measured, never idle. Browser throttling may delay checks. No camera footage is uploaded. Meetings, teaching, training, client meetings, travel and breaks are exempt. Clock actions and exception requests remain available.</p><div class="settings-grid">${settingFields.map(([k,l,t])=>settingForm(k,l,t,c[k])).join('')}</div><label>Working weekdays</label><div class="inline-tools">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label style="margin:0"><input style="width:auto;min-height:0" type="checkbox" name="weekday" value="${i}" ${c.workingDays.includes(i)?'checked':''}> ${d}</label>`).join('')}</div></section><section class="panel"><div class="section-tools"><h2>Office locations & geofences</h2><button type="button" id="add-fence" class="secondary">Add office</button></div><div id="geofence-list">${c.geofences.map(f=>fenceRow(f)).join('')}</div><p class="subtle">Coordinates are required only for approved office locations. A location mismatch is evidence for review, not proof of misconduct.</p></section><section class="panel"><div class="section-tools"><h2>Scoped rules & exemptions</h2><button type="button" id="add-override" class="secondary">Add scoped rule</button></div><div id="override-list">${c.overrides.map(x=>overrideRow(x)).join('')}</div><label>Monitoring-exempt employees<select name="exemptEmployees" multiple size="5">${settings.employees.map(e=>`<option value="${esc(e.employee_id)}" ${c.exemptEmployees.includes(e.employee_id)?'selected':''}>${esc(e.employee_name)} · ${esc(e.employee_id)}</option>`).join('')}</select></label><p class="subtle">Employee exemptions disable required page/camera checks, optional presence/activity checks and working-hour alerts. Attendance still records clock events.</p></section><button type="submit">Save all attendance rules</button></form><section class="panel"><h2>Data retention</h2><p>Remove expired location, device, work-trace and optional photo data. Clock events, session totals, approvals and correction audit records remain.</p><button class="secondary" id="retention-cleanup">Apply retention now</button><p class="subtle">Retention also runs when P&C opens this workspace, at most once a day. Email, push and WhatsApp delivery require a connected provider; in-app notifications are available.</p></section>`;$('#add-fence').onclick=()=>$('#geofence-list').insertAdjacentHTML('beforeend',fenceRow({name:'',latitude:'',longitude:'',radius:150,contexts:['Office','Hybrid']}));$('#add-override').onclick=()=>$('#override-list').insertAdjacentHTML('beforeend',overrideRow({rules:{}}));$('#attendance-view').onclick=e=>{if(e.target.matches('[data-remove]'))e.target.closest('.row-list').remove()};$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),out={...c};for(const [k,,t]of settingFields)out[k]=t==='bool'?f.get(k)==='Yes':t==='number'||t==='trace'?parseInt(f.get(k)):f.get(k);out.workingDays=f.getAll('weekday').map(Number);out.exemptEmployees=f.getAll('exemptEmployees');out.geofences=[...document.querySelectorAll('.fence-row')].map(r=>{const get=k=>r.querySelector('[name='+k+']').value;return{name:get('officeName'),latitude:Number(get('latitude')),longitude:Number(get('longitude')),radius:Number(get('radius')),contexts:[...r.querySelector('[name=fenceContexts]').selectedOptions].map(o=>o.value)}});out.overrides=[...document.querySelectorAll('.override-row')].map(r=>{const get=k=>r.querySelector('[name='+k+']').value;return{employeeId:get('scopeEmployee'),department:get('scopeDepartment'),context:get('scopeContext'),from:get('scopeFrom'),to:get('scopeTo'),rules:{start:get('scopeStart'),end:get('scopeEnd'),graceMinutes:Number(get('scopeGrace')),scheduleEnabled:get('scopeEnabled')==='Yes'}}});await mutate('/config',{data:out,version:settings.version})};$('#retention-cleanup').onclick=()=>dialog('Apply configured retention','<p>This removes evidence older than the saved retention periods. Attendance totals and correction audit history are retained.</p>',()=>mutate('/retention',{}),'Apply retention')}
function fenceRow(f){return `<div class="row-list fence-row"><div class="settings-grid">${field('officeName','Office name','text',f.name,'required')}${field('latitude','Latitude','number',f.latitude,'required step="any" min="-90" max="90"')}${field('longitude','Longitude','number',f.longitude,'required step="any" min="-180" max="180"')}${field('radius','Radius (metres)','number',f.radius,'required min="10" max="50000"')}<label>Work contexts<select multiple name="fenceContexts" size="3">${contexts.map(x=>`<option ${f.contexts.includes(x)?'selected':''}>${x}</option>`).join('')}</select></label></div><button type="button" data-remove class="plain">Remove office</button></div>`}
function overrideRow(x){const r=x.rules;return `<div class="row-list override-row"><div class="settings-grid"><label>Employee<select name="scopeEmployee"><option value="">All employees</option>${settings.employees.map(e=>`<option value="${esc(e.employee_id)}" ${e.employee_id===x.employeeId?'selected':''}>${esc(e.employee_name)}</option>`).join('')}</select></label>${select('scopeDepartment','Department',['',...settings.departments],x.department||'')}${select('scopeContext','Work context',['',...contexts],x.context||'')}${field('scopeFrom','Effective from','date',x.from||'')}${field('scopeTo','Effective until','date',x.to||'')}${field('scopeStart','Start time','time',r.start||settings.data.start)}${field('scopeEnd','End time','time',r.end||settings.data.end)}${field('scopeGrace','Grace minutes','number',r.graceMinutes??settings.data.graceMinutes,'min="0" max="180"')}${select('scopeEnabled','Working-hour alerts',['No','Yes'],r.scheduleEnabled?'Yes':'No')}</div><button type="button" data-remove class="plain">Remove scoped rule</button></div>`}
function privacy(){const r=data.rules;$('#attendance-view').innerHTML=`<section class="panel privacy-content"><h2>Attendance & Work Trace Privacy</h2><p>Nadi records attendance to support accurate working-time records, approved work arrangements and corrections. Work-presence evidence is not a productivity measurement and does not automatically affect MPC or disciplinary decisions.</p><h3>What is collected</h3><ul><li>Your existing Employee ID and server-confirmed clock/break times, work context and explanations.</li><li>Location and accuracy at clock actions when you grant permission; device reference, browser information and network IP where available.</li><li>Work status and task updates you choose to submit.</li>${r.traceLevel>1||r.requiredPresence||r.focusedCameraRequired?'<li>Aggregated mouse-activity and no-mouse-movement seconds while this Nadi page is visible and in focus. A 60-second window follows each actual mouse movement. Keyboard input and clicks do not count; no keys, typed text, clipboard, passwords or desktop-app content are collected. Outside-page time is reported separately as not measured and is never added to idle time.</li>':'<li>Aggregated activity checks are currently disabled.</li>'}${r.traceLevel===3?'<li>Visible acknowledgement requests while working remotely, subject to approved leave/work-context exemptions.</li>':''}${r.requiredPresence?'<li>Available and Focused Work require the Nadi attendance page to remain open; it may stay in the background during work in other applications. Page check-ins are sent about every three minutes when the browser permits. A missing connection is shown as unverified after '+r.heartbeatGraceMinutes+' minutes; browser throttling, sleep or connection loss can cause this. It is not automatically an absence.</li>':''}${r.focusedCameraRequired?'<li>Focused Work requires you to open your webcam with browser permission. A visible preview stays on your device. Only camera availability is reported; no video, audio, images or facial recognition data are transmitted by this check. The camera may stay enabled while Nadi is open in the background. Closing this page, leaving Today, ending work or choosing an exempt activity stops it.</li>':''}${r.cameraEnabled?'<li>A selfie is optional after acknowledgement. The camera starts only when you choose “Open camera”, shows a preview, and stops when the dialog closes. No microphone or continuous recording.</li>':'<li>Optional presence photos are disabled.</li>'}</ul><h3>Who can see it</h3><p>You can see your own attendance. Assigned managers can see their team’s attendance and work updates. P&C can review location evidence, optional photos, approvals and amendments. Top Management receives aggregated workforce information.</p><h3>Retention</h3><p>Location and device evidence: ${r.locationRetentionDays} days. Work-trace evidence: ${r.traceRetentionDays} days. Optional photos: ${r.photoRetentionDays} days. P&C applies retention; session totals and correction audit records are retained as employment records.</p><h3>Permissions & limitations</h3><p>You control browser location and camera permissions. Missing or poor GPS is shown as unverified; location risk flags require human review. The webpage cannot read mouse movement in Excel, email or other applications. That time is not measured; your chosen work status and clocked-in time remain. No mouse movement may include reading or typing and is not proof of inactivity. System-wide mouse detection requires a separate desktop tool. Page focus, visibility and camera state are browser-reported signals, not proof of physical presence or productivity. Focused Work cannot be selected without the required camera; camera problems, a closed page or an unverified connection are shown for review. Working outside Nadi is not an idle or absence finding. Clocking and correction/exception requests remain available.</p><h3>How to correct a record</h3><p>Open My attendance → Requests & corrections. Explain a missed clock or exception and propose times if needed. Assigned managers review where configured; P&C makes the final amendment. Original clock events and decisions remain in the audit trail.</p><h3>Notifications</h3><p>In-app request updates and attendance reminders are available. Email, push and WhatsApp are not connected in this release.</p></section>`}
async function load(quiet=false,query=''){
 const sequence=++loadSequence,selectedView=view;tabs();$('#attendance-view').setAttribute('aria-busy','true');
 const area=selectedView==='privacy'?'/privacy':selectedView==='settings'?'/config':['dashboard','reviews'].includes(selectedView)?'/dashboard':selectedView==='analytics'?'/metrics':selectedView==='history'?'/history':'/me';
 try{const result=await api(area+query);if(sequence!==loadSequence)return;
  if(selectedView==='settings'){settings=result;settingsView()}else{data=result;({privacy,dashboard,reviews,analytics,history,requests,today}[selectedView]||today)()}
  lastRefresh=Date.now();if(isAdmin&&!maintenanceChecked){maintenanceChecked=true;api('/maintenance',jsonOpts({})).catch(()=>{maintenanceChecked=false})}
 }catch(e){if(sequence!==loadSequence)return;if(!quiet)$('#attendance-view').innerHTML='<section class="panel"><h2>Attendance unavailable</h2><p>'+esc(e.message)+'</p><button id="reload-attendance">Try again</button></section>';if($('#reload-attendance'))$('#reload-attendance').onclick=()=>load();message(e.message,'error')}
 finally{if(sequence===loadSequence)$('#attendance-view').setAttribute('aria-busy','false')}
}
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null}
function photoDialog(id){dialog('Optional presence photo','<p>A photo is optional. You have already acknowledged the request. The camera stays off until you choose to open it.</p><button type="button" id="open-camera" class="secondary">Open camera</button><video id="camera-preview" autoplay playsinline muted hidden></video>',async()=>{if(!stream)throw new Error('Open the camera, or cancel to continue without a photo.');const video=$('#camera-preview'),canvas=document.createElement('canvas');canvas.width=640;canvas.height=Math.round(640*video.videoHeight/video.videoWidth);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.75));stopCamera();const f=new FormData();f.set('photo',new File([blob],'presence.jpg',{type:'image/jpeg'}));await api('/presence/'+id+'/photo',{method:'POST',body:f});message('Optional photo saved privately.');},'Save optional photo');$('#open-camera').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});$('#camera-preview').hidden=false;$('#camera-preview').srcObject=stream}catch{ $('#dialog-error').textContent='Camera unavailable. You can cancel; attendance is unaffected.'}}}
$('#dialog-form').onsubmit=async e=>{e.preventDefault();$('#save-dialog').disabled=true;try{await dialogSubmit(new FormData(e.target));$('#attendance-dialog').close();stopCamera()}catch(error){$('#dialog-error').textContent=error.message}finally{$('#save-dialog').disabled=false}};for(const id of ['close-dialog','cancel-dialog'])$('#'+id).onclick=()=>{$('#attendance-dialog').close();stopCamera()};$('#attendance-dialog').addEventListener('close',stopCamera);$('#attendance-dialog').addEventListener('cancel',stopCamera);
document.addEventListener('pointermove',e=>{if(!e.isTrusted||e.pointerType!=='mouse'||!pageHasFocus())return;const p={x:e.screenX,y:e.screenY};if(!lastMousePosition||p.x!==lastMousePosition.x||p.y!==lastMousePosition.y)lastMouseMove=Date.now();lastMousePosition=p},{passive:true});
function pageBoundary(){sampleActivity();sampleFocused=pageHasFocus();lastMouseMove=0;lastMousePosition=null;sendHeartbeat(true,true);renderMonitorLive()}
document.addEventListener('visibilitychange',()=>{pageBoundary();if(document.visibilityState==='visible'&&Date.now()-lastRefresh>60000)load(true)});
window.addEventListener('blur',pageBoundary);window.addEventListener('focus',pageBoundary);
window.addEventListener('pagehide',()=>{sampleActivity();sendHeartbeat(true,true,{pageOpen:false,pageVisible:false,pageFocused:false});stopFocusCamera()});
window.addEventListener('online',()=>{message('Connection restored. Page activity during the connection gap is not estimated. Retry any pending clock action using its request reference.');traceActive=traceIdle=traceUnmeasured=0;lastSample=Date.now();sampleFocused=pageHasFocus();sendHeartbeat(false,true);load(true)});
window.addEventListener('offline',()=>{traceActive=traceIdle=traceUnmeasured=0;lastSample=Date.now();sampleFocused=pageHasFocus();stopFocusCamera();message('You are offline. Page presence may become overdue and Focused Work needs the camera reopened after reconnecting. Clock events need server confirmation.','warning')});
setInterval(()=>{const clock=serverNow();$('#server-clock').textContent=clock.toLocaleTimeString('en-MY',{timeZone:'Asia/Kuala_Lumpur',hour:'2-digit',minute:'2-digit',second:'2-digit'});if(view==='today'&&data?.session&&!data.session.clock_out){const s=data.session,total=Math.max(0,(clock-Date.parse(s.clock_in))/1000),breakSeconds=s.break_seconds+(s.break_start?Math.max(0,(clock-Date.parse(s.break_start))/1000):0);if($('#work-duration'))$('#work-duration').textContent=hours(Math.max(0,total-breakSeconds));if($('#break-duration'))$('#break-duration').textContent=hours(breakSeconds)}},1000);
setInterval(()=>{sampleActivity();renderMonitorLive()},5000);
setInterval(async()=>{if(!management&&view==='today'&&navigator.onLine)await sendHeartbeat(true);if(document.visibilityState==='visible'&&['today','dashboard','reviews'].includes(view)&&!busy&&!$('#attendance-dialog').open)load(true)},180000);
setInterval(async()=>{if(document.visibilityState!=='visible'||!navigator.onLine||busy||$('#attendance-dialog').open||!['today','dashboard','reviews'].includes(view))return;try{const r=await api('/revision');if(lastRevision&&lastRevision!==r.revision)await load(true);lastRevision=r.revision}catch{}},60000);
function parseMonitor(record){try{return JSON.parse(record.monitor_json||'{}')}catch{return {}}}
function focusCameraLive(){return !!focusStream?.getVideoTracks().some(t=>t.readyState==='live'&&t.enabled&&!t.muted)}
function focusedCameraApplies(d=data){return !!d?.rule?.focusedCameraRequired&&!['Teaching','Training','Travel','On Leave'].includes(d?.context)}
function pageHasFocus(){return view==='today'&&document.visibilityState==='visible'&&document.hasFocus()}
function monitorState(){return {pageOpen:view==='today',pageVisible:view==='today'&&document.visibilityState==='visible',pageFocused:pageHasFocus(),activitySource:'nadi-mouse',cameraState:focusCameraLive()?'live':'off'}}
function sampleActivity(){const current=Date.now(),gap=Math.max(0,Math.floor((current-lastSample)/1000)),delta=Math.min(180,gap),focused=pageHasFocus();lastSample=current;if(!management&&view==='today'&&data?.session&&!data.session.clock_out&&!data.session.break_start&&navigator.onLine&&activityApplies()){if(gap>10||!sampleFocused||!focused||data.monitoring?.cameraRequired&&!focusCameraLive())traceUnmeasured+=delta;else if(current-lastMouseMove<60000)traceActive+=delta;else traceIdle+=delta}sampleFocused=focused}
function activityApplies(){return !data?.monitoring?.exempt&&!['Meeting','Teaching','Training','Client Meeting','Travel','Break','Offline'].includes(selfStatus)&&(data?.rule?.traceLevel>1||data?.monitoring?.required)}
function activityTotals(m){return hours(m?.activeSeconds||0)+' mouse activity / '+hours(m?.idleSeconds||0)+' no mouse movement / '+hours(m?.unmeasuredSeconds||0)+' not measured'+(m?.legacyActiveSeconds||m?.legacyIdleSeconds?'<br>Earlier page-input totals: '+hours(m.legacyActiveSeconds)+' active / '+hours(m.legacyIdleSeconds)+' idle (previous method)':'')}
function monitoringPanel(d){return '<div class="monitoring-panel"><h3>Page presence & webcam</h3><p id="monitor-live" role="status">'+esc(d.monitoring?.state||'Not required')+'</p><p class="subtle">Keep this page open during Available and Focused Work. Only mouse movement while Nadi is in focus contributes to mouse activity, using a 60-second activity window. Keyboard input and clicks do not count. Switching to Excel, email or another application keeps your work status and clocked-in time; that time is shown as “Outside Nadi — not measured”, never idle.</p><p class="subtle">Totals are sent about every three minutes, including while the page is in the background when the browser allows. No mouse movement can include reading or typing; it does not establish inactivity. Measuring mouse activity across desktop apps requires a separate desktop tool.</p><p class="subtle">Focused Work requires a webcam when enabled by P&C. The camera can stay enabled when you switch apps while this page stays open. The preview stays on your device; only camera availability is reported. No video is recorded or streamed. Closing this page, leaving Today, ending work or choosing an exempt activity stops it.</p><video id="focus-camera-preview" autoplay playsinline muted hidden aria-label="Your private webcam preview"></video><div class="inline-tools"><button type="button" id="open-focus-camera" class="secondary">Open webcam for Focused Work</button><button type="button" id="stop-focus-camera" class="plain">Stop webcam</button></div><p class="subtle">Last page check-in: '+time(d.monitoring?.lastCheckIn)+'<br>'+activityTotals(d.monitoring)+'</p></div>'}
function dashboardMonitoring(m){if(!m)return '—';return pill(m.state)+'<br>'+esc(m.status)+'<br><span class="subtle">'+time(m.lastCheckIn)+(m.cameraRequired?' · Camera '+esc(m.cameraState):'')+'<br>'+activityTotals(m)+'<br>Mouse activity measures interaction, not productivity.</span>'}
function attachFocusPreview(){const video=$('#focus-camera-preview');if(video&&focusStream){video.srcObject=focusStream;video.hidden=false}renderMonitorLive()}
function renderMonitorLive(){const node=$('#monitor-live');if(!node)return;const focused=$('#work-update [name=status]')?.value==='Focused Work',required=focusedCameraApplies();node.textContent=focused&&required&&!focusCameraLive()?'Webcam required · open the camera before saving Focused Work':activityApplies()&&!pageHasFocus()?'Outside Nadi — not measured'+(focusCameraLive()?' · Webcam enabled':''):focused&&required?'Webcam enabled · keep this page open':data?.monitoring?.state||'Not required'}
function stopFocusCamera(){const old=focusStream;focusStream=null;old?.getTracks().forEach(t=>t.stop());const video=$('#focus-camera-preview');if(video){video.srcObject=null;video.hidden=true}renderMonitorLive()}
async function openFocusCamera(){if(focusCameraLive()){attachFocusPreview();return}if(!navigator.mediaDevices?.getUserMedia)throw new Error('This browser cannot open a webcam. Request a camera exception from P&C.');try{focusStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:320},height:{ideal:240}},audio:false});for(const track of focusStream.getVideoTracks()){track.addEventListener('ended',()=>{stopFocusCamera();traceActive=traceIdle=traceUnmeasured=0;sendHeartbeat(false,true);message('Webcam disconnected. Focused Work requires the camera to be reopened or an approved exception.','warning')});track.addEventListener('mute',()=>{renderMonitorLive();sendHeartbeat(false,true)});track.addEventListener('unmute',()=>{renderMonitorLive();sendHeartbeat(false,true)})}attachFocusPreview()}catch{stopFocusCamera();throw new Error('Camera permission or a working webcam is required for Focused Work. Allow camera access, or request an exception from P&C.')}}
async function sendHeartbeat(interval=false,keepalive=false,override={}){
 if(management||view!=='today'||!data?.session||data.session.clock_out||data.session.break_start||!navigator.onLine||!activityApplies())return;
 const currentMonitor={...monitorState(),...override};
 if(heartbeatBusy){heartbeatQueued={sessionId:data.session.id,monitor:currentMonitor,keepalive};return}
 heartbeatBusy=true;
 try{
  sampleActivity();
  if(!heartbeatPending){const total=traceActive+traceIdle+traceUnmeasured,sendInterval=interval||total>0,consumed=sendInterval?{active:traceActive,idle:traceIdle,unmeasured:traceUnmeasured}:{active:0,idle:0,unmeasured:0},scale=total>180?180/total:1,counts=sendInterval?{active:Math.floor(traceActive*scale),idle:Math.floor(traceIdle*scale),unmeasured:Math.floor(traceUnmeasured*scale)}:{active:0,idle:0,unmeasured:0};heartbeatPending={init:jsonOpts({sessionId:data.session.id,interval:sendInterval,activeSeconds:counts.active,idleSeconds:counts.idle,unmeasuredSeconds:counts.unmeasured,monitor:currentMonitor}),sessionId:data.session.id,counts:consumed}}
  if(heartbeatPending.sessionId!==data.session.id){heartbeatPending=null;return}
  const submitted=heartbeatPending.counts;await api('/heartbeat',{...heartbeatPending.init,keepalive});heartbeatPending=null;traceActive=Math.max(0,traceActive-submitted.active);traceIdle=Math.max(0,traceIdle-submitted.idle);traceUnmeasured=Math.max(0,traceUnmeasured-submitted.unmeasured);lastTrace=Date.now();
 }catch(error){if(error.status&&error.status<500){heartbeatPending=null;traceActive=traceIdle=traceUnmeasured=0}if(error.status!==429&&error.status!==409)message('Page connection could not be confirmed. Time in another app is not treated as idle. Keep Nadi open and check your connection.','warning')}
 finally{
  // A focus, camera or closing event must not be lost behind an in-flight interval.
  if(heartbeatQueued){const queued=heartbeatQueued;heartbeatQueued=null;try{await api('/heartbeat',{...jsonOpts({sessionId:queued.sessionId,interval:false,monitor:queued.monitor}),keepalive:queued.keepalive})}catch{}}
  heartbeatBusy=false;
 }
}

